import{_ as s,O as a,o,c as i,a as r,i as n,f as d}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.20　国家能力、政策执行与治理","description":"","frontmatter":{"title":"D.20　国家能力、政策执行与治理","xkChars":650,"xkLessons":{"D.20":{"title":"D.20　国家能力、政策执行与治理","lead":"问“治理有没有能力”之前，先问哪项任务、哪个环节、哪个群体以及什么期限；程序内成功不能代替资格总体覆盖。","explanation":["原文定位：第4837—4852行，原站定位/theory/appendix-d/d-20#section-d-20。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“国家能力应落实到具体任务、层级和组织资源。”国家形成、财政军事动员、行政自主、嵌入、合法性、认同、公共服务是不同过程。一处执行强不证明其他处也强；观察到服从也不能只归为认同，可能还涉及依赖、处罚或惯例等待检解释。[T-main]","政策链至少区分问题进入议程、规则制定、资格界定、预算落实、一线执行、通知申请、核定给付、实际使用、申诉纠错。前一项完成是后一项可能的条件，却不代替后一项实际到达；例如预算到机构不等于申请人可用服务。[T-main]","分母必须逐环明确。资格者、被通知者、申请者、获批者、领取者和持续可用者各有集合与时间。批准率可以真实提高，同时总体领取覆盖仍低；若采用家庭计资格、个人计领取，必须说明映射与重复，不能直接相除。[T-main]","一线裁量既可能补规则不适配，也可能造成排斥。应查任务冲突、资源、实际选择与监督，不把所有绕行先判失职或创新。多中心治理也不是多开几个机构，而是各自拥有真实权限、资源与协调；若任命、资金、选样、执行和复核均受同一关口控制，机构数量不证明独立性。[T-main]","地方知识有用，不意味着当地强者代表租客、少数、未参与者和未来使用者。上级联系可提供资源与救济，也可控制目标和个案。自主性要说明相对谁、在哪项事务：免政党控制、行政规则裁量、地方/用户改规权不在同一轴上。[T-main]","原文随机检查例是教学条件：记录更完整可以是监督的局部改善，却不能证明普通申请人的救济已提速。临时援助的生活改善也可真实成立，同时长期财政接续和选择权仍未解决。制度外部性应说明哪种决策核算遗漏了何种成本，不必等终局法律责任判定才允许描述有据损害。[T-main]","真实参照：澳大利亚2023年7月7日Robodebt皇家委员会报告建议13.1要求新项目设计与实施听取一线人员，13.2要求管理层审查并回应他们的反馈。本题新增观察点是政策执行链中的“收到一线意见”和“管理回应”不同，不重复将其当法律授权案例；这里仅核建议文本，不宣称建议已落实或申请人已获救济。[P-ROBO]","§7.3.7—7.3.8提供反馈与条件势场接口，第十至十一部分追踪圈层通道与事件，第十四部分检查规范选择和授权，§15.3.5接制度模块。连接不是把国家能力简化成一个HV分数；具体任务仍需领域资料。[T-main]","研究导航20.01国家形成与财政军事国家（Tilly等）问资源动员如何形成；20.02合法性支配与认同（Weber等）区分服从依据；20.03国家能力自主与嵌入（Mann/Evans/Fukuyama等）需指任务和关系；20.04街头官僚（Lipsky）关注一线裁量；20.05多中心与公地（Ostrom）关注真实权限协调。本题解释本书入口，不冒称已通读这些学者全部著作。[T-main]","20.06公共政策实施反馈接整条政策链；20.07中央地方关系核尺度资源与控制；20.08腐败俘获委托代理查谁任命支付选样复核；20.09民主威权官僚技术治理比较要同任务同群体而非总排名；20.10治理失败脆弱重建要分功能中断与后续承接，不能从一次失败宣布国家所有能力归零。[T-main]"],"argumentSteps":["固定任务、层级、对象总体和期限。","逐环列政策链状态及真实资料，不用上游成功补下游。","把分母、家庭个人映射和持续时间写清。","查一线裁量与监督控制结构，区分多中心名义和实际权限。","保留局部改善与遗漏损害，效果、合法性和规范选择另核。"],"distinctions":[{"leftTitle":"批准率","leftText":"获批人数/申请人数。","rightTitle":"总体覆盖","rightText":"到达资格总体的比例及持续可用性。"},{"leftTitle":"记录完整","leftText":"监督或记录终点。","rightTitle":"实际救济","rightText":"决定资源和生活结果，需另外取证。"},{"leftTitle":"机构多","leftText":"组织数量。","rightTitle":"多中心治理","rightText":"真实分权和协调关系。"},{"leftTitle":"自主性","leftText":"相对某主体、某事项的空间。","rightTitle":"总强弱","rightText":"不能替代各轴分析。"}],"boundaries":["原文教学反例：检查改善记录，个案救济仍慢。","教学反例：申请者批准率高，便认定未申请资格者也获覆盖。","原文边界：上级联系可兼有资源与控制，不可单向赋义。"],"questions":["批准率高能说明人人得到福利吗？","地方参与为何不能自动代表全体？","委员会建议存在是否等于实施？"],"diagramPath":"/reading-assets/S-D-20/figures/d20-chain.png","caseLinks":[{"title":"2023年Robodebt委员会要求把一线反馈接入管理回应","href":"https://robodebt.royalcommission.gov.au/publications/report"}],"caseNotes":[{"title":"2023年Robodebt委员会要求把一线反馈接入管理回应","text":"2023年7月7日报告建议13.1要求设计实施阶段的一线咨询，13.2要求管理层审查回应反馈。","sourceLabel":"Royal Commission into the Robodebt Scheme: Report建议清单","sourceUrl":"https://robodebt.royalcommission.gov.au/publications/report","sourceLocator":"2023-07-07报告页面，Chapter13，Recommendation13.1 Consultation process与13.2 Feedback processes；更正版说明2023-07-11","boundary":"仅建议内容，不证明已经执行、个案救济变快或全部国家治理能力；本题看执行链新增观察点。","href":"https://robodebt.royalcommission.gov.au/publications/report"}],"sourceRefs":[{"section":"D.20","start_line":4837,"end_line":4852,"startLine":4837,"endLine":4852}],"outputId":"section-d-20","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：四个比率不要混算","text":"人工资格总体100人，40人申请、30人获批、24人实际领取。批准率30/40=75%；获批者领取率24/30=80%；申请者领取率24/40=60%；资格总体领取覆盖24/100=24%。四个分数都正确，却回答不同问题；没有后续月份记录，不能称持续覆盖24%。","assumptions":"虚构同窗口、同个人单位、嵌套人群且无重复。","boundary":"不代表任何真实政策效果，家庭单位或跨窗需重算。"},{"title":"教学构造：监督改善的有限结论","text":"人工检查后记录缺漏从10份降至2份，但申诉处理时间没有取得资料。可以登记记录终点的变化；若要归因于检查还需因果比较，若要声称救济加快更需相应时间及下游资料。","assumptions":"数字完全虚构，不把前后差直接当因果。","boundary":"不抹去已观察记录改善，也不拿它证明所有治理有效。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：检查改善记录，个案救济仍慢。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：申请者批准率高，便认定未申请资格者也获覆盖。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：上级联系可兼有资源与控制，不可单向赋义。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"批准率高能说明人人得到福利吗？","answer":"不能，未申请者及未领取者可能不在分母，持续可用还另核。","basis":"政策链。"},{"question":"地方参与为何不能自动代表全体？","answer":"需要代表关系及遗漏位置，地方强者的声音未必覆盖所有受影响者。","basis":"权力与覆盖。"},{"question":"委员会建议存在是否等于实施？","answer":"不等于，需管理改变、执行及申请人结果的独立资料。","basis":"真实案例边界。"}],"figures":[{"path":"/reading-assets/S-D-20/figures/d20-chain.png","alt":"议程规则资格预算执行申请给付使用申诉依次不同，不保证自动到达。","caption":"据D.20政策链。"},{"path":"/reading-assets/S-D-20/figures/d20-denominators.png","alt":"人工100资格40申请30批准24领取，四个比率分母不同。","caption":"教学构造非政策数据。"},{"path":"/reading-assets/S-D-20/figures/d20-governance.png","alt":"裁量、权限、资源、任命选样复核分别核；建议不等于落实。","caption":"据D.20及委员会13.1—13.2建议。"}],"diagramBrief":"三图显示政策链、人工分母及自主/监督关系，不制作国家总能力排行榜。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未完成学者原作全体比较，也未验证任何国家总能力排名。","官方建议页当前直接重取超时；事实限已核建议正文，不报告实施进度。"],"taskId":"S-D-20","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.20，第4837—4852行","claim_support":["全部政策链、分母、自主性、教学例及十项专题入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-ROBO","title":"Royal Commission into the Robodebt Scheme: Report建议清单","url":"https://robodebt.royalcommission.gov.au/publications/report","source_type":"primary","version_or_date":"2023-07-07；页面载2023-07-11更正","locator":"2023-07-07报告页面，Chapter13，Recommendation13.1 Consultation process与13.2 Feedback processes；更正版说明2023-07-11","claim_support":["委员会要求新项目设计实施时真正听取一线人员，并建立管理层审查回应反馈的过程。"],"limits":["已读官网建议段；当前直接重取超时，官方页面检索正文仍可核两条完整建议。未读990页全报告，不据建议推实施或救济效果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-20/lecture.md","sourcesPath":"/reading-assets/S-D-20/sources.json","sourceSlicePath":"/reading-assets/S-D-20/source/S-D-20.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-20/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-20.md","filePath":"theory/appendix-d/d-20.md"}'),c={name:"theory/appendix-d/d-20.md"};function p(l,e,u,m,b,h){const t=a("SectionLesson");return o(),i("div",null,[e[0]||(e[0]=r('<div class="theory-source"><h1 id="section-d-20" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.20</span><span class="xk-num__gap">　</span></span>国家能力、政策执行与治理 <a class="header-anchor" href="#section-d-20" aria-label="Permalink to &quot;D.20　国家能力、政策执行与治理 {#section-d-20}&quot;">​</a></h1><p>正文连接：§7.3.7—7.3.8；§10—11；§14；§15.3.5。研究入口：20.01—20.10。</p><p>国家形成、财政军事动员、行政自主、嵌入、支配合法性、社会认同与公共服务并非同一过程。服从可以有多种原因，行政到达可以与权利缺口并存。国家能力应落实到具体任务、层级和组织资源，不以一个总强弱尺度替代分析。</p><p>政策链可以分为问题进入议程、规则制定、资格界定、预算落实、一线执行、通知申请、核定给付、实际使用和申诉纠错。每一环有不同分母与时间。资格者、申请者、获批者和实际领取者的比率不能混算；计算规则使用家庭还是个人单位，也可能改变结果。</p><p>一线裁量既可弥补规则不适配，也可形成偏差和排斥，须结合任务冲突、资源与监督。多中心治理需要真实的权限与协调，不是机构数量多；反腐与监督要查谁任命、谁支付、谁选择样本、谁有执行和复核权。地方知识的价值不等当地强者代表所有居民。</p><p>教学例：随机检查促使记录更完整，但对普通申请人的救济仍慢。监督效果与个案救济各有成立范围。临时援助也可以真实改善生活，同时留下财政接续与选择权问题。制度外部性需明确被哪种决策核算排除，不要求先有终局法律责任才能记录损害。</p><p>自主性须注明相对谁以及对什么：免于政党控制、行政规则裁量、地方或使用者改规权并非同一轴。上级联系可以提供资源与救济，也可能控制目标和个案。批准率、曾领取比例和持续可用服务具有不同分母与时间条件；已经观察到的局部改善应保留，资格总体的覆盖则不能由程序内成功者补齐。</p><p>专题定位：20.01 国家形成与财政军事国家：Tilly 等；20.02 合法性、支配与国家认同：Weber 等；20.03 国家能力、自主性与嵌入：Mann、Evans、Fukuyama 等；20.04 街头官僚与政策执行：Lipsky；20.05 多中心治理与公地：Ostrom；20.06 公共政策、实施与反馈；20.07 中央地方关系与尺度；20.08 腐败、俘获与委托代理；20.09 民主、威权、官僚与技术治理比较；20.10 治理失败、国家脆弱与重建。</p></div>',1)),n(t,{section:"D.20"}),e[1]||(e[1]=d("div",{class:"theory-source"},null,-1))])}const f=s(c,[["render",p]]);export{g as __pageData,f as default};
